import type { Tool, Schema } from "ai";
import type { ValidationSchema, StandardRecord, ZodUnknownSchema } from "./typeAliases.js";
import type { AIProviderName } from "./providers.js";
import type { AnalyticsData, TokenUsage } from "./analytics.js";
import type { EvaluationData } from "./evaluation.js";
import type { ChatMessage, ConversationMemoryConfig } from "./conversation.js";
import type { MiddlewareFactoryOptions } from "./middlewareTypes.js";
import type { JsonValue } from "./common.js";
import type { TextContent, ImageContent } from "./content.js";
/**
 * Generate function options type - Primary method for content generation
 * Supports multimodal content while maintaining backward compatibility
 */
export type GenerateOptions = {
    input: {
        text: string;
        images?: Array<Buffer | string>;
        content?: Array<TextContent | ImageContent>;
    };
    output?: {
        format?: "text" | "structured" | "json";
    };
    provider?: AIProviderName | string;
    model?: string;
    temperature?: number;
    maxTokens?: number;
    systemPrompt?: string;
    schema?: ValidationSchema;
    tools?: Record<string, Tool>;
    timeout?: number | string;
    disableTools?: boolean;
    enableEvaluation?: boolean;
    enableAnalytics?: boolean;
    context?: StandardRecord;
    evaluationDomain?: string;
    toolUsageContext?: string;
    conversationHistory?: Array<{
        role: string;
        content: string;
    }>;
    factoryConfig?: {
        domainType?: string;
        domainConfig?: StandardRecord;
        enhancementType?: "domain-configuration" | "streaming-optimization" | "mcp-integration" | "legacy-migration" | "context-conversion";
        preserveLegacyFields?: boolean;
        validateDomainData?: boolean;
    };
    streaming?: {
        enabled?: boolean;
        chunkSize?: number;
        bufferSize?: number;
        enableProgress?: boolean;
        fallbackToGenerate?: boolean;
    };
};
/**
 * Generate function result type - Primary output format
 * Future-ready for multi-modal outputs while maintaining text focus
 */
export type GenerateResult = {
    content: string;
    outputs?: {
        text: string;
    };
    provider?: string;
    model?: string;
    usage?: TokenUsage;
    responseTime?: number;
    toolCalls?: Array<{
        toolCallId: string;
        toolName: string;
        args: StandardRecord;
    }>;
    toolResults?: unknown[];
    toolsUsed?: string[];
    toolExecutions?: Array<{
        name: string;
        input: StandardRecord;
        output: unknown;
    }>;
    enhancedWithTools?: boolean;
    availableTools?: Array<{
        name: string;
        description: string;
        parameters: StandardRecord;
    }>;
    analytics?: AnalyticsData;
    evaluation?: EvaluationData;
    factoryMetadata?: {
        enhancementApplied: boolean;
        enhancementType?: string;
        domainType?: string;
        processingTime?: number;
        configurationUsed?: StandardRecord;
        migrationPerformed?: boolean;
        legacyFieldsPreserved?: boolean;
    };
    streamingMetadata?: {
        streamingUsed: boolean;
        fallbackToGenerate?: boolean;
        chunkCount?: number;
        streamingDuration?: number;
        streamId?: string;
        bufferOptimization?: boolean;
    };
};
/**
 * Unified options for both generation and streaming
 * Supports factory patterns and domain configuration
 */
export type UnifiedGenerationOptions = GenerateOptions & {
    preferStreaming?: boolean;
    streamingFallback?: boolean;
};
/**
 * Enhanced provider type with generate method
 */
export type EnhancedProvider = {
    generate(options: GenerateOptions): Promise<GenerateResult>;
    getName(): string;
    isAvailable(): Promise<boolean>;
};
/**
 * Factory-enhanced provider type
 * Supports domain configuration and streaming optimizations
 */
export type FactoryEnhancedProvider = EnhancedProvider & {
    generateWithFactory(options: UnifiedGenerationOptions): Promise<GenerateResult>;
    getDomainSupport(): string[];
    getStreamingCapabilities(): {
        supportsStreaming: boolean;
        maxChunkSize: number;
        bufferOptimizations: boolean;
    };
};
/**
 * Text generation options type (consolidated from core types)
 */
export type TextGenerationOptions = {
    prompt?: string;
    input?: {
        text: string;
    };
    provider?: AIProviderName;
    model?: string;
    temperature?: number;
    maxTokens?: number;
    systemPrompt?: string;
    schema?: ZodUnknownSchema | Schema<unknown>;
    tools?: Record<string, Tool>;
    timeout?: number | string;
    disableTools?: boolean;
    maxSteps?: number;
    enableEvaluation?: boolean;
    enableAnalytics?: boolean;
    context?: Record<string, JsonValue>;
    evaluationDomain?: string;
    toolUsageContext?: string;
    conversationHistory?: Array<{
        role: string;
        content: string;
    }>;
    conversationMessages?: ChatMessage[];
    conversationMemoryConfig?: Partial<ConversationMemoryConfig>;
    originalPrompt?: string;
    middleware?: MiddlewareFactoryOptions;
    expectedOutcome?: string;
    evaluationCriteria?: string[];
};
/**
 * Text generation result (consolidated from core types)
 */
export type TextGenerationResult = {
    content: string;
    provider?: string;
    model?: string;
    usage?: TokenUsage;
    responseTime?: number;
    toolsUsed?: string[];
    toolExecutions?: Array<{
        toolName: string;
        executionTime: number;
        success: boolean;
        serverId?: string;
    }>;
    enhancedWithTools?: boolean;
    availableTools?: Array<{
        name: string;
        description: string;
        server: string;
        category?: string;
    }>;
    analytics?: AnalyticsData;
    evaluation?: EvaluationData;
};
/**
 * Enhanced result type with optional analytics/evaluation
 */
export type EnhancedGenerateResult = GenerateResult & {
    analytics?: AnalyticsData;
    evaluation?: EvaluationData;
};
